function admin(){return `<section class="wrap"><div class="eyebrow">MINGO / QUẢN TRỊ</div><div class="section-head"><h1 style="font-size:40px">Quản lý hành trình</h1><button class="outline" onclick="adminLogout()">Đăng xuất Admin</button></div><div class="inline-note"><button class="outline" style="float:right" onclick="this.parentElement.remove()" aria-label="Đóng thông báo">×</button>Đã đăng nhập tài khoản quản trị riêng. Dữ liệu nghiệp vụ của bản trải nghiệm vẫn được lưu trên trình duyệt này.</div><div class="admin-shell"><aside class="admin-nav">${[['overview','Tổng quan'],['tours','Quản lý tour'],['bookings','Đơn đặt tour'],['destinations','Điểm đến']].map(([id,n])=>`<button class="${adminTab===id?'active':''}" onclick="adminTab='${id}';render()">${n}</button>`).join('')}</aside><div>${adminContent()}</div></div></section>`}
function adminContent(){if(adminTab==='destinations')return `<h2>34 tỉnh thành</h2><p class="muted">Địa danh và đặc sản theo địa giới mới.</p><div class="province-grid" style="grid-template-columns:repeat(2,1fr)">${PROVINCES.map(provinceCard).join('')}</div>`;if(adminTab==='tours')return `<div class="section-head"><h2>Tour & lịch khởi hành</h2><button onclick="editTour()">+ Thêm tour</button></div><div class="table-scroll"><table><thead><tr><th>Tour</th><th>Giá / khách</th><th>Chỗ / đợt</th><th>Thao tác</th></tr></thead><tbody>${tours.map(t=>`<tr><td>${esc(t.title)}<br><small>${esc(t.province)} · ${t.hidden?'Đã ẩn':'Đang bán'}</small></td><td>${money(t.price)}</td><td>${t.dates.map(d=>date(d)+': '+Math.max(0,remaining(t,d))+'/'+t.capacity).join('<br>')}</td><td><button onclick="editTour('${t.id}')">Sửa</button><button class="outline" onclick="toggleTour('${t.id}')">${t.hidden?'Hiện lại':'Ẩn'}</button></td></tr>`).join('')}</tbody></table></div>`;return `${adminTab==='overview'?`<h2>Tổng quan</h2><div class="metrics"><div class="metric"><small>Tour đang bán</small><b>${tours.filter(t=>!t.hidden).length}</b></div><div class="metric"><small>Đơn đặt tour</small><b>${bookings.length}</b></div><div class="metric"><small>Tiền đã thu</small><b style="font-size:20px">${money(bookings.filter(b=>b.paid&&b.status!=='cancelled').reduce((s,b)=>s+b.total,0))}</b></div></div>`:'<h2>Đơn đặt tour</h2><p class="muted">Xác nhận đơn, cập nhật thanh toán hoặc hủy.</p>'}${!bookings.length?'<div class="empty"><h3>Chưa có đơn đặt tour</h3><p>Đơn mới sẽ xuất hiện sau khi khách hoàn thành form đặt tour.</p></div>':`<div class="table-scroll"><table><thead><tr><th>Mã / khách</th><th>Chuyến đi</th><th>Tổng tiền</th><th>Trạng thái</th><th>Xử lý</th></tr></thead><tbody>${bookings.map(b=>`<tr><td>${b.id}<br>${esc(b.name)}<br><small>${esc(b.phone)}</small></td><td>${esc(b.title)}<br><small>${date(b.date)} · ${b.people} khách</small></td><td>${money(b.total)}<br><small>${b.paid?'Đã thu tiền':'Chưa thanh toán'}</small></td><td>${statusName[b.status]}</td><td>${b.status==='pending'?`<button onclick="updateBooking('${b.id}','confirm')">Xác nhận</button>`:''}${b.status==='confirmed'?`<button onclick="updateBooking('${b.id}','pay')">${b.paid?'Hoàn tiền':'Đã thu tiền'}</button>`:''}${b.status!=='cancelled'?`<button class="outline" onclick="cancelBooking('${b.id}',true)">Hủy</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}`}
function updateBooking(id,action){let b=bookings.find(b=>b.id===id);if(action==='confirm'&&b.status==='pending')b.status='confirmed';if(action==='pay'&&b.status==='confirmed')b.paid=!b.paid;save();render()}function toggleTour(id){let t=tours.find(t=>t.id===id);if(!confirm(t.hidden?'Hiện lại tour này?':'Ẩn tour này khỏi danh sách khách hàng?'))return;t.hidden=!t.hidden;save();render()}
function editTour(id){let t=tours.find(t=>t.id===id)||{title:'',price:2000000,days:3,capacity:24,province:PROVINCES[0].name,dates:['2026-12-05'],desc:''};modal(`<h2>${id?'Sửa tour':'Thêm tour'}</h2><form class="form" onsubmit="saveTour(event,'${id||''}')"><label>Tên tour<input name="title" value="${esc(t.title)}" required maxlength="120"></label><label>Tỉnh thành<select name="province">${PROVINCES.map(p=>`<option ${p.name===t.province?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Giá mỗi khách<input name="price" type="number" min="1" value="${t.price}" required></label><label>Số ngày<input name="days" type="number" min="1" max="30" value="${t.days}" required></label><label>Sức chứa mỗi đợt<input name="capacity" type="number" min="1" max="100" value="${t.capacity}" required></label><label>Các ngày khởi hành (YYYY-MM-DD, cách nhau bằng dấu phẩy)<input name="dates" value="${t.dates.join(',')}" required></label><label>Mô tả<textarea name="desc" required>${esc(t.desc)}</textarea></label><button>Lưu tour</button></form>`)}
function saveTour(e,id){e.preventDefault();let f=new FormData(e.target),dates=f.get('dates').split(',').map(x=>x.trim());if(dates.some(d=>!/^\d{4}-\d{2}-\d{2}$/.test(d)||isNaN(Date.parse(d))))return toast('Ngày không hợp lệ. Dùng YYYY-MM-DD.');let old=tours.find(t=>t.id===id),cap=+f.get('capacity');if(old&&old.dates.some(d=>{let count=old.capacity-remaining(old,d);return count>cap||(count>0&&!dates.includes(d))}))return toast('Không thể xóa ngày đã có khách hoặc giảm sức chứa dưới số chỗ đã đặt.');let p=province(f.get('province')),t={...old,id:id||'tour'+Date.now(),title:f.get('title'),province:p.name,price:+f.get('price'),days:+f.get('days'),capacity:cap,dates,desc:f.get('desc'),place:old?.place||p.attractions[0],hidden:old?.hidden||false};if(old)tours=tours.map(x=>x.id===id?t:x);else tours.push(t);save();$('#modal').close();render();toast('Đã lưu tour.')}

const baseAdminContent=adminContent;
adminContent=function(){let html=baseAdminContent();if(adminTab==='destinations')return `<h2>Quản lý địa danh & đặc sản</h2><label>Chọn tỉnh<select id="edit-province" onchange="destinationEditor(this.value)"><option value="">Chọn tỉnh thành</option>${PROVINCES.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div id="destination-editor"></div>`;if(adminTab==='overview'){const pending=bookings.filter(b=>b.status==='pending').length;const upcoming=tours.filter(t=>!t.hidden&&t.dates.some(d=>d>=new Date().toISOString().slice(0,10))).sort((a,b)=>a.dates[0].localeCompare(b.dates[0])).slice(0,5);const popular=tours.map(t=>({t,n:bookings.filter(b=>b.tourId===t.id&&b.status!=='cancelled').reduce((s,b)=>s+b.people,0)})).filter(x=>x.n).sort((a,b)=>b.n-a.n).slice(0,5);html=`<div class="inline-note"><strong>${pending} đơn đang chờ xác nhận</strong></div><h3>Tour sắp khởi hành</h3>${upcoming.map(t=>`<p>${esc(t.title)} · ${date(t.dates.filter(d=>d>=new Date().toISOString().slice(0,10)).sort()[0])}</p>`).join('')}<h3>Tour được đặt nhiều nhất</h3>${popular.length?popular.map(x=>`<p>${esc(x.t.title)} · ${x.n} khách</p>`).join(''):'<p>Chưa có dữ liệu đặt tour.</p>'}`+html;}if(adminTab==='tours'||adminTab==='bookings'){html=`<div class="toolbar"><input placeholder="${adminTab==='tours'?'Tìm tên tour hoặc tỉnh':'Tìm tên khách, SĐT, mã đơn'}" oninput="filterAdminRows()" id="admin-search"><select id="admin-status" onchange="filterAdminRows()"><option value="">Tất cả trạng thái</option>${(adminTab==='tours'?['Đang bán','Đã ẩn']:Object.values(statusName)).map(s=>`<option>${s}</option>`).join('')}</select></div>`+html;}return html;};
function filterAdminRows(){const q=$('#admin-search').value.toLocaleLowerCase('vi'),s=$('#admin-status').value;document.querySelectorAll('.table-scroll tbody tr').forEach(r=>r.hidden=!r.textContent.toLocaleLowerCase('vi').includes(q)||!!s&&!r.textContent.includes(s))}
const originalEditTour=editTour;editTour=function(id){originalEditTour(id);const t=tours.find(t=>t.id===id),form=$('#modal-body form');form.querySelector('input[name="dates"]').parentElement.outerHTML=`<fieldset><legend>Ngày khởi hành</legend><div id="date-list">${(t?.dates||['2026-12-05']).map(d=>dateInput(d)).join('')}</div><button type="button" class="outline" onclick="$('#date-list').insertAdjacentHTML('beforeend',dateInput(''))">+ Thêm ngày</button><input type="hidden" name="dates"></fieldset>`;form.querySelector('button:not([type])').insertAdjacentHTML('beforebegin',`<label>Loại hình<select name="category">${['Biển đảo','Núi & thiên nhiên','Văn hóa & khám phá'].map(c=>`<option ${tourType(t||{})===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Ảnh tour<input type="file" id="cover-upload" accept="image/jpeg,image/png,image/webp"></label><p class="notice">Chọn ảnh JPG, PNG hoặc WebP dưới 2 MB.</p><label>Nguồn ảnh<input name="coverSource" value="${esc(t?.coverSource||'')}"></label><label>Điểm đón<input name="pickup" value="${esc(t?.pickup||'')}"></label><label>Bao gồm<textarea name="includes">${esc(t?.includes||'')}</textarea></label><label>Không bao gồm<textarea name="excludes">${esc(t?.excludes||'')}</textarea></label><fieldset><legend>Lịch trình từng ngày</legend><div id="itinerary-editor"></div></fieldset>`);const count=form.querySelector('[name="days"]');const sync=()=>{$('#itinerary-editor').innerHTML=Array.from({length:Math.min(30,Math.max(1,+count.value||1))},(_,i)=>`<label>Ngày ${i+1}<textarea data-day required>${esc(t?.itinerary?.[i]||'Tham quan, nghỉ ngơi và trải nghiệm địa phương.')}</textarea></label>`).join('')};sync();count.addEventListener('change',sync)};
function dateInput(d){return `<div class="date-entry"><input type="date" value="${esc(d)}" required><button type="button" class="outline" onclick="this.parentElement.remove()">Bỏ ngày</button></div>`}
const originalSaveTour=saveTour;saveTour=async function(e,id){e.preventDefault();const form=e.target,dates=[...form.querySelectorAll('#date-list input')].map(x=>x.value);if(!dates.length||dates.some(x=>!x))return toast('Chọn ít nhất một ngày khởi hành.');form.querySelector('[name="dates"]').value=[...new Set(dates)].sort().join(',');const f=new FormData(form);let cover=tours.find(t=>t.id===id)?.cover;const file=$('#cover-upload').files[0];if(file){if(file.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Ảnh phải là JPG, PNG hoặc WebP dưới 2 MB.');cover=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});}const extras={cover,category:f.get('category'),coverSource:f.get('coverSource'),pickup:f.get('pickup'),includes:f.get('includes'),excludes:f.get('excludes'),itinerary:[...form.querySelectorAll('[data-day]')].map(x=>x.value)};originalSaveTour(e,id);if($('#modal').open)return;const target=tours.find(t=>t.id===id)||tours[tours.length-1];Object.assign(target,extras);try{save();render()}catch{toast('Bộ nhớ trình duyệt đầy. Vui lòng chọn ảnh nhỏ hơn.')}};
function destinationEditor(id){const p=PROVINCES.find(p=>String(p.id)===id);if(!p){$('#destination-editor').innerHTML='';return}$('#destination-editor').innerHTML=['attractions','specialties'].map(k=>`<h3>${k==='attractions'?'Địa danh':'Đặc sản'}</h3>${p[k].map((n,i)=>`<div class="destination-row"><span>${esc(n)}</span><button onclick="editDestination(${p.id},'${k}',${i})">Sửa</button><button class="outline" onclick="deleteDestination(${p.id},'${k}',${i})">Xóa</button></div>`).join('')}<button class="outline" onclick="editDestination(${p.id},'${k}',-1)">+ Thêm</button>`).join('')}
function editDestination(id,k,i){const p=PROVINCES.find(p=>p.id===id),n=p[k][i]||'',m=IMAGE_MAP[n]||{};modal(`<h2>${i<0?'Thêm':'Sửa'} ${k==='attractions'?'địa danh':'đặc sản'}</h2><form class="form" onsubmit="saveDestination(event,${id},'${k}',${i})"><label>Tên<input name="name" required value="${esc(n)}"></label><label>Mô tả ngắn<textarea name="description" required>${esc(m.description||'')}</textarea></label><label>Địa chỉ ảnh HTTPS<input name="url" type="url" required value="${esc(m.url?.startsWith('/')?location.origin+m.url:m.url||'')}"></label><label>Nguồn ảnh<input name="source" required value="${esc(m.source||'')}"></label><button>Lưu</button></form>`)}
function saveDestination(e,id,k,i){e.preventDefault();const f=new FormData(e.target),p=PROVINCES.find(p=>p.id===id),name=f.get('name').trim(),url=f.get('url');if(!url.startsWith('https://'))return toast('Dùng địa chỉ ảnh HTTPS.');if(p[k].some((x,j)=>x===name&&j!==i))return toast('Tên đã có trong danh sách.');if(i<0)p[k].push(name);else p[k][i]=name;IMAGE_MAP[name]={url,source:f.get('source'),description:f.get('description')};saveDestinations();$('#modal').close();destinationEditor(String(id))}
function deleteDestination(id,k,i){const p=PROVINCES.find(p=>p.id===id);if(p[k].length<=1)return toast('Giữ ít nhất một mục cho mỗi danh sách.');if(!confirm('Xóa '+p[k][i]+' khỏi danh sách?'))return;p[k].splice(i,1);saveDestinations();destinationEditor(String(id))}
function saveDestinations(){localStorage.setItem('mingo-destinations',JSON.stringify({provinces:PROVINCES,images:IMAGE_MAP}))}
